"""Chat-first local interface. Model and record text are inserted as text, never HTML."""

PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>LocalCodingAgent | Chat</title><style>
:root{color-scheme:light dark;--bg:#fff;--side:#f4f5f7;--text:#23252a;--muted:#656b75;--line:#e0e2e6;--accent:#176b5b;--bubble:#f5f6f8;font:16px/1.55 system-ui,Segoe UI,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}button,input,textarea{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,textarea:focus-visible,a:focus-visible{outline:3px solid #e3a52a;outline-offset:2px}.shell{height:100dvh;display:grid;grid-template-columns:280px minmax(0,1fr)}aside{background:var(--side);border-right:1px solid var(--line);display:flex;flex-direction:column;min-width:0;padding:14px;gap:12px}.brand{font-size:1.1rem;font-weight:700}.new-chat{border:1px solid var(--line);border-radius:10px;background:var(--bg);padding:10px;text-align:left}.search{width:100%;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)}.conversation-list{overflow:auto;flex:1}.conversation{width:100%;border:0;background:transparent;color:var(--text);text-align:left;padding:9px;border-radius:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.conversation:hover,.conversation.selected{background:#e5e9ed}.side-bottom{display:flex;justify-content:space-between;align-items:center;gap:8px}.side-bottom a,.plain{color:var(--muted);border:0;background:none;text-decoration:none;padding:6px}.main{display:flex;flex-direction:column;min-width:0;height:100dvh}.top{height:58px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 22px}.top select{max-width:220px;padding:7px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)}.messages{flex:1;overflow:auto;padding:26px max(20px,calc((100% - 850px)/2));scroll-behavior:smooth}.welcome{max-width:760px;margin:14vh auto 0;text-align:center}.welcome h1{font-size:2rem;margin:.3rem}.welcome p{color:var(--muted)}.suggestions{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin-top:24px}.suggestions button{background:var(--bg);color:var(--text);border:1px solid var(--line);border-radius:20px;padding:9px 13px}.message{margin:0 auto 22px;max-width:820px;white-space:pre-wrap;overflow-wrap:anywhere}.message.user{background:var(--bubble);padding:12px 16px;border-radius:18px;width:fit-content;max-width:min(85%,820px);margin-right:0}.message.assistant{padding:0 10px}.message-label{font-size:.78rem;color:var(--muted);margin-bottom:3px}.markdown-text{white-space:pre-wrap;overflow-wrap:anywhere}.code{position:relative;background:#161b22;color:#f0f2f5;border-radius:10px;margin:12px 0;padding:42px 14px 14px;overflow:auto}.code pre{margin:0;white-space:pre;overflow:auto}.copy{position:absolute;right:9px;top:8px;border:1px solid #59616d;border-radius:6px;background:#252c35;color:white;padding:4px 8px}.composer-wrap{padding:10px 20px max(16px,env(safe-area-inset-bottom));}.composer{max-width:850px;margin:auto;border:1px solid var(--line);border-radius:18px;padding:9px 11px;box-shadow:0 3px 14px #0000000c}.composer textarea{resize:vertical;min-height:52px;max-height:220px;width:100%;border:0;outline:none;background:transparent;color:var(--text);padding:6px}.controls{display:flex;align-items:center;justify-content:space-between}.hint{font-size:.78rem;color:var(--muted)}.send,.stop{border:0;border-radius:10px;background:var(--accent);color:white;padding:8px 14px;font-weight:650}.stop{background:#8b312a}.status{max-width:850px;margin:0 auto 4px;color:var(--muted);font-size:.88rem;min-height:1.3em}.error{color:#9c2d25}.login{position:fixed;inset:0;background:var(--bg);display:grid;place-items:center;padding:20px}.login-card{width:min(460px,100%);border:1px solid var(--line);border-radius:16px;padding:24px}.login input{display:block;width:100%;margin:8px 0 12px;padding:10px;border:1px solid var(--line);border-radius:8px}.login button{background:var(--accent);color:#fff;border:0;border-radius:8px;padding:10px 14px}.hidden{display:none!important}details{color:var(--muted);font-size:.88rem} :root[data-theme="dark"]{--bg:#1b1c1e;--side:#222427;--text:#eceef1;--muted:#a9afb8;--line:#393d43;--accent:#4bb39b;--bubble:#2a2c30} :root[data-theme="dark"] .conversation:hover,:root[data-theme="dark"] .conversation.selected{background:#34373c} :root[data-theme="dark"] .message.user{background:#2b2d31} @media(max-width:700px){.shell{grid-template-columns:1fr}.shell.sidebar-closed{grid-template-columns:0 minmax(0,1fr)}aside{position:absolute;z-index:4;width:280px;height:100dvh;box-shadow:5px 0 25px #0002}.sidebar-closed aside{display:none}.messages{padding:20px 14px}.top{padding:0 12px}.top select{max-width:155px}.welcome{margin-top:10vh}}
@media(prefers-color-scheme:dark){:root{--bg:#1b1c1e;--side:#222427;--text:#eceef1;--muted:#a9afb8;--line:#393d43;--accent:#4bb39b;--bubble:#2a2c30}.conversation:hover,.conversation.selected{background:#34373c}.message.user{background:#2b2d31}}
</style></head><body><div id="shell" class="shell sidebar-closed"><aside><div class="brand">LocalCodingAgent</div><button id="newChat" class="new-chat">＋ New chat</button><input id="searchChats" class="search" type="search" placeholder="Search conversations" aria-label="Search conversations"><div id="conversations" class="conversation-list" aria-label="Recent conversations"></div><div class="side-bottom"><button id="theme" class="plain" aria-label="Toggle light or dark theme">Theme</button><a href="/developer">Developer view</a></div></aside><main class="main"><div class="top"><button id="sidebarToggle" class="plain" aria-label="Show or hide conversations">☰</button><span id="chatTitle">New chat</span><label class="hint">Model <select id="model" aria-label="Chat model"></select></label></div><div id="messages" class="messages" aria-live="polite"></div><div id="status" class="status" role="status" aria-live="polite"></div><div class="composer-wrap"><div class="composer"><textarea id="prompt" aria-label="Message" placeholder="Ask anything…" maxlength="12000"></textarea><div class="controls"><span class="hint">Enter to send · Shift+Enter for a new line</span><div><button id="stop" class="stop hidden">Stop</button> <button id="send" class="send">Send</button></div></div></div></div></main></div>
<div id="login" class="login"><div class="login-card"><h1>Open your local assistant</h1><p>Copy the one-run token from the PowerShell window running LocalCodingAgent. It is not part of the web address.</p><label for="token">Dashboard token</label><input id="token" type="password" autocomplete="current-password"><button id="connect">Open assistant</button><p id="loginError" class="error" role="status"></p><details><summary>Lost the token?</summary><p>Stop only the dashboard with Ctrl+C in its PowerShell window, then start it again. Keep the window open to copy the new token.</p></details></div></div>
<script nonce="__NONCE__">
let token='',conversationId='',controller=null,sending=false,items=[],models=[];const $=id=>document.getElementById(id);$('shell').style.visibility='hidden';$('shell').setAttribute('inert','');$('shell').setAttribute('aria-hidden','true');const modelLabel=$('model').parentElement,settings=document.createElement('details'),settingsTitle=document.createElement('summary');settingsTitle.textContent='Settings';settings.append(settingsTitle,modelLabel);$('theme').parentElement.before(settings);
async function api(path,options={}){const response=await fetch(path,{...options,headers:{...(options.headers||{}),Authorization:'Bearer '+token}});let data={};try{data=await response.json()}catch{}if(!response.ok)throw Error(data.error||('Request failed ('+response.status+').'));return data}
const unannotatedApi=api;api=async(path,options={})=>{const data=await unannotatedApi(path,options);if(path==='/api/chat/models'){window.lcaInstalledModels=data.installed||[];window.lcaChatConnection=data.connection||'unavailable';$('connectionState').textContent=window.lcaChatConnection==='ready'?'Mac model connection ready at startup':'Mac model was unavailable at startup';annotateModelOptions()}return data};const connectionState=document.createElement('span');connectionState.id='connectionState';connectionState.className='hint';connectionState.textContent='Checking local model…';$('chatTitle').before(connectionState);function annotateModelOptions(){for(const option of $('model').options){if(option.dataset.statusShown)continue;option.textContent+=' — '+(window.lcaInstalledModels.includes(option.value)?'installed on Mac':'not confirmed on Mac');option.dataset.statusShown='true'}}const modelObserver=new MutationObserver(annotateModelOptions);modelObserver.observe($('model'),{childList:true});
function addText(parent,value,className){const el=document.createElement('div');el.className=className;el.textContent=value;parent.append(el);return el}
function renderTextMarkdown(parent,text){let list=null;for(const line of text.split('\n')){if(!line.trim()){list=null;continue}const heading=line.match(/^#{1,3}\s+(.+)$/);if(heading){list=null;const h=document.createElement('h'+Math.min(3,(line.match(/^#+/)||[''])[0].length));h.textContent=heading[1];parent.append(h);continue}const bullet=line.match(/^\s*(?:[-*]|\d+\.)\s+(.+)$/);if(bullet){if(!list){list=document.createElement('ul');parent.append(list)}const li=document.createElement('li');li.textContent=bullet[1];list.append(li);continue}list=null;const p=document.createElement('p');p.className='markdown-text';p.textContent=line;parent.append(p)}}
function renderMarkdownSafe(parent,text){const parts=text.split(/```([^\n`]*)\n([\s\S]*?)```/g);for(let i=0;i<parts.length;i+=3){if(parts[i])renderTextMarkdown(parent,parts[i]);if(i+2<parts.length){const box=document.createElement('div');box.className='code';const label=document.createElement('span');label.className='message-label';label.textContent=parts[i+1]||'Code';box.append(label);const button=document.createElement('button');button.className='copy';button.textContent='Copy';const pre=document.createElement('pre');pre.textContent=parts[i+2].replace(/\n$/,'');button.onclick=async()=>{try{await navigator.clipboard.writeText(pre.textContent);button.textContent='Copied'}catch{button.textContent='Copy unavailable'}};box.append(button,pre);parent.append(box)}}}
function renderMessages(messages){const box=$('messages');box.replaceChildren();if(!messages.length){const welcome=document.createElement('div');welcome.className='welcome';const h=document.createElement('h1');h.textContent='What can I help with?';const p=document.createElement('p');p.textContent='Ask a question, explore an idea, or get help writing code. You do not need to select a project for general questions.';const suggestions=document.createElement('div');suggestions.className='suggestions';for(const prompt of ['Hello, what can you help me with?','Write a Python function that finds duplicate filenames.']){const b=document.createElement('button');b.textContent=prompt;b.onclick=()=>{$('prompt').value=prompt;$('prompt').focus()};suggestions.append(b)}welcome.append(h,p,suggestions);box.append(welcome);return}for(const message of messages){const article=document.createElement('article');article.className='message '+message.role;const who=document.createElement('div');who.className='message-label';who.textContent=message.role==='user'?'You':'Local assistant';article.append(who);if(message.role==='assistant')renderMarkdownSafe(article,message.content);else{const content=document.createElement('div');content.textContent=message.content;article.append(content)}box.append(article)}box.scrollTop=box.scrollHeight}
function renderConversations(rows){const box=$('conversations');box.replaceChildren();const query=$('searchChats').value.trim().toLowerCase();for(const row of rows.filter(item=>!query||item.title.toLowerCase().includes(query))){const b=document.createElement('button');b.className='conversation'+(row.id===conversationId?' selected':'');b.textContent=row.title;b.title=row.title;b.onclick=()=>openConversation(row.id);box.append(b)}if(!box.childElementCount){const empty=document.createElement('p');empty.className='hint';empty.textContent=query?'No matching conversations.':'Your conversations will appear here.';box.append(empty)}}
async function loadConversations(){const result=await api('/api/chat/conversations');items=result.conversations;renderConversations(items)}
async function newConversation(){const row=await api('/api/chat/conversations',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});conversationId=row.id;$('chatTitle').textContent='New chat';renderMessages([]);await loadConversations();$('prompt').focus()}
async function openConversation(id){const row=await api('/api/chat/conversations/'+id);conversationId=row.id;$('chatTitle').textContent=row.title;renderMessages(row.messages);renderConversations(items)}
async function connect(){token=$('token').value;try{const result=await api('/api/chat/models');models=result.models;const select=$('model');select.replaceChildren();for(const name of models){const option=document.createElement('option');option.value=name;option.textContent=name;select.append(option)}await loadConversations();if(items.length)await openConversation(items[0].id);else await newConversation();$('login').classList.add('hidden');$('prompt').focus()}catch(error){$('loginError').textContent=error.message;token=''}}
async function send(){const text=$('prompt').value.trim();if(!text||controller)return;if(!conversationId)await newConversation();$('prompt').value='';$('status').textContent='Thinking…';$('send').classList.add('hidden');$('stop').classList.remove('hidden');const user={role:'user',content:text},assistant={role:'assistant',content:''};const old=await api('/api/chat/conversations/'+conversationId);const messages=[...old.messages,user];renderMessages([...messages,assistant]);const activeId=conversationId;controller=new AbortController();try{const response=await fetch('/api/chat/conversations/'+activeId+'/messages',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({message:text,model:$('model').value}),signal:controller.signal});if(!response.ok){const detail=await response.json().catch(()=>({}));throw Error(detail.error||'The assistant could not respond.')}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();for(const line of lines){if(!line)continue;const event=JSON.parse(line);if(event.type==='status')$('status').textContent=event.text;if(event.type==='token'){assistant.content+=event.text;renderMessages([...messages,assistant])}if(event.type==='error')throw Error(event.message);if(event.type==='done'&&event.cancelled)$('status').textContent='Stopped. Partial response saved.'}}if(buffer.trim()){const event=JSON.parse(buffer);if(event.type==='error')throw Error(event.message)}}catch(error){if(error.name!=='AbortError')$('status').textContent=error.message;else $('status').textContent='Stopped.'}finally{controller=null;$('send').classList.remove('hidden');$('stop').classList.add('hidden');if(!$('status').textContent.startsWith('Stopped'))$('status').textContent='';await loadConversations();const current=await api('/api/chat/conversations/'+activeId);conversationId=activeId;$('chatTitle').textContent=current.title;renderMessages(current.messages)}}
async function stop(){if(!conversationId)return;try{await api('/api/chat/conversations/'+conversationId+'/stop',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'})}catch{}$('status').textContent='Stopping…'}
$('connect').onclick=connect;$('newChat').onclick=newConversation;$('send').onclick=send;$('stop').onclick=stop;$('searchChats').oninput=()=>renderConversations(items);$('sidebarToggle').onclick=()=>$('shell').classList.toggle('sidebar-closed');$('prompt').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();send()}};$('theme').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.style.colorScheme=dark?'dark':'light'};
async function sendChat(){const text=$('prompt').value.trim();if(!text||sending)return;sending=true;$('send').classList.add('hidden');$('stop').classList.remove('hidden');$('status').textContent='Thinking…';let activeId='';controller=new AbortController();try{if(!conversationId)await newConversation();activeId=conversationId;const old=await api('/api/chat/conversations/'+activeId);const messages=[...old.messages,{role:'user',content:text}],assistant={role:'assistant',content:''};$('prompt').value='';renderMessages([...messages,assistant]);const response=await fetch('/api/chat/conversations/'+activeId+'/messages',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({message:text,model:$('model').value}),signal:controller.signal});if(!response.ok){const detail=await response.json().catch(()=>({}));throw Error(detail.error||'The assistant could not respond.')}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const result=await reader.read();if(result.done)break;buffer+=decoder.decode(result.value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();for(const line of lines){if(!line)continue;const event=JSON.parse(line);if(event.type==='status')$('status').textContent=event.text;if(event.type==='token'){assistant.content+=event.text;renderMessages([...messages,assistant])}if(event.type==='error')throw Error(event.message);if(event.type==='done'&&event.cancelled)$('status').textContent='Stopped. Partial response saved.'}}}catch(error){$('status').textContent=error.name==='AbortError'?'Stopped.':error.message}finally{controller=null;sending=false;$('send').classList.remove('hidden');$('stop').classList.add('hidden');if(!$('status').textContent.startsWith('Stopped')&&$('status').textContent!==''){$('status').textContent=$('status').textContent==='Thinking…'||$('status').textContent==='Writing your response…'?'':$('status').textContent}try{await loadConversations();if(activeId){const current=await api('/api/chat/conversations/'+activeId);conversationId=activeId;$('chatTitle').textContent=current.title;renderMessages(current.messages)}}catch(error){if(!$('status').textContent)$('status').textContent='Could not refresh conversation history.'}}}
$('send').onclick=sendChat;$('prompt').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendChat()}};
const openConversationUnchecked=openConversation;openConversation=async id=>{if(!sending)await openConversationUnchecked(id)};$('newChat').onclick=()=>{if(!sending)newConversation()};
const connectUnchecked=connect;connect=async()=>{await connectUnchecked();if(token){$('shell').style.visibility='visible';$('shell').removeAttribute('inert');$('shell').removeAttribute('aria-hidden')}};$('connect').onclick=connect;
</script></body></html>'''
